         */mergedInto: String?) {
        self.id = id
        self.kind = kind
        self.name = name
        self.summary = summary
        self.labels = labels
        self.attrsJson = attrsJson
        self.groupId = groupId
        self.createdAt = createdAt
        self.expiredAt = expiredAt
        self.mergedInto = mergedInto
    }

    

    
}

