/**
 * Everything that can go wrong across the boundary. Swift sees an
 * `enum NacreError: Error` with associated values.
 */
public 
enum NacreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * An argument did not parse (a malformed id, a timestamp without a
     * UTC offset, an unknown episode source).
     */
    case InvalidInput(
        /**
         * What was wrong, naming the offending field.
         */message: String
    )
    /**
     * A host protocol failed, or kept failing until the pipeline gave up.
     */
    case Provider(
        /**
         * The failure as reported by the host, with pipeline context.
         */message: String
    )
    /**
     * A replayed model was asked something no recording answers. Offline
     * replay refuses to guess; the canonical request is included so the
     * diff against the recordings file is mechanical.
     */
    case ReplayMiss(
        /**
         * The unmatched request, canonically rendered.
         */canonicalRequest: String
    )
    /**
     * Any other model-side failure (decode, recording I/O, format).
     */
    case Model(
        /**
         * The underlying model error, rendered.
         */message: String
    )
    /**
     * A grit storage failure.
     */
    case Storage(
        /**
         * The underlying grit error, rendered.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension NacreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNacreError: FfiConverterRustBuffer {
    typealias SwiftType = NacreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> NacreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Provider(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .ReplayMiss(
            canonicalRequest: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Model(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: NacreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Provider(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .ReplayMiss(canonicalRequest):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(canonicalRequest, into: &buf)
            
        
        case let .Model(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


