private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_nacre_swift_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_nacre_swift_checksum_func_version() != 50159) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_add_episode() != 1813) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_add_episode_replay() != 39175) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_edges_in_group() != 25309) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_episodes_in_group() != 46002) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_mentions_of() != 43344) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_node_history() != 48528) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_nodes_in_group() != 58156) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_previous_episodes() != 6714) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_search_edges() != 13681) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_search_edges_replay() != 18621) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_memory_traverse() != 23097) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_embeddingprovider_embed() != 33871) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_method_llmprovider_chat() != 27856) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_nacre_swift_checksum_constructor_memory_open() != 23772) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitEmbeddingProvider()
    uniffiCallbackInitLlmProvider()
    return InitializationResult.ok
}()

// Make the ensure init function public so that other modules which have external type references to
// our types can call it.
public func uniffiEnsureNacreSwiftInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

